  "design_rules": {
    "parent_order_split": "买家一次下单按商家拆单：1 parent_order → N order（每商家一单）。支付模块以 parent_order 为单位对接，payment_ref_no 引用支付模块单号",
    "order_status_enum": "order_status 枚举：pending_payment(待付款) / paid(已付款) / partially_shipped(部分发货) / shipped(全部发货) / partially_received(部分签收) / completed(交易完成) / cancelled(已取消)",
    "item_status_enum": "item_status 枚举：pending(待发货) / refunding(退款中) / refunded(已退款) / shipped(已发货) / received(已签收) / cancelled(已取消)",
    "fulfillment_status_enum": "fulfillment_status 枚举：pending(待发货) / shipped(已发货) / received(已签收)",
    "payment_status_enum": "payment_status 枚举：pending(待支付) / paid(已支付) / failed(支付失败)",
    "refund_status_enum": "refund_status 枚举：pending(待处理) / processing(处理中) / completed(已完成) / rejected(已拒绝)",
    "refund_type_enum": "refund_type 枚举：pre_shipment(发货前退款)。后续扩展退货退款时新增类型",
    "request_channel_enum": "request_channel 枚举：email(邮件)。后续扩展自助申请时新增 app / web",
    "operator_type_enum": "operator_type 枚举：admin(运营人员) / system(系统自动)。参考库存模块 inventory_ledger 的操作人设计模式",
    "address_snapshot": "订单创建时快照收货地址（address_id UUID + 10 个快照字段）。字段命名对齐地址模块：address_line1/state_province/postal_code。recipient_first_name + last_name 拆分存储（报关需要），recipient_name 冗余拼接用于展示。地址模块后续更新不影响已有订单",
    "price_snapshot": "order_item 在创建时快照 listing_price 为 unit_price。listing 价格变动不影响已有订单",
    "condition_snapshot": "order_item 快照 product_inspection.grade 为 condition_grade",
    "fulfillment_boundary": "订单模块管「发什么」（order_fulfillment + item），物流模块管「怎么发」（承运商/追踪/轨迹）。跨模块关联：fulfillment_no = shipments.business_order_no（API 注册时传入），tracking_no = shipments.tracking_no（缓存用于展示）。物流模块是独立信息服务，不直接引用订单实体",
    "order_completion_rule": "订单完成判定：所有 order_fulfillment 状态为 received → 订单标记 completed。推导路径：fulfillment.received → item.received → order.completed",
    "refund_blocks_shipping": "退款审批通过后，order_item.item_status 变为 refunding → 该商品不得纳入任何履约单发货",
    "cart_to_order_flow": "购物车到订单数据流：cart_item.listing_id → listing.product_id + listing.listing_price → 创建 order_item（product_id + listing_id + 快照价格/成色）",
    "currency_rule": "同一订单内所有金额使用相同 currency_code。parent_order.total_amount = SUM(order.order_amount)",
    "user_id_redundancy": "order.user_id 与 parent_order.user_id 冗余存储，避免查询「我的订单」时 join parent_order 表",
    "merchant_id_vs_seller_id": "商品模块用 seller_id 引用 merchants.id（卖方语境），订单模块用 merchant_id 引用同一实体（商家语境）。同一 FK 目标，不同业务语义"
  }
}
